  "ai_overview": {
    "text_blocks": [
      {
        "type": "paragraph",
        "snippet": "You can file your income tax return online by logging into the Income Tax e-Filing Portal.",
        "snippet_links": [
          {
            "text": "Income Tax e-Filing Portal",
            "link": "https://www.incometax.gov.in/iec/foportal/"
          }
        ],
        "reference_indexes": [
          0
        ]
      },
      {
        "type": "heading",
        "snippet": "Prerequisites & Documents Needed"
      },
      {
        "type": "list",
        "list": [
          {
            "snippet": "Form 16 provided by your employer."
          },
          {
            "snippet": "Form 26AS and AIS (Annual Information Statement) downloaded from the portal."
          },
          {
            "snippet": "Active and linked PAN and Aadhaar."
          },
          {
            "snippet": "Pre-validated bank account for tax refunds."
          }
        ],
        "reference_indexes": [
          1,
          2
        ]
      },
      {
        "type": "heading",
        "snippet": "Step-by-Step Filing Process (ITR-1 for Salaried Employees)"
      },
      {
        "type": "list",
        "list": [
          {
            "snippet": "Log in to the Income Tax e-Filing Portal using your PAN/User ID and password.",
            "reference_indexes": [
              0,
              3
            ]
          },
          {
            "snippet": "Go to the top menu and select e-File > Income Tax Returns > File Income Tax Return.",
            "reference_indexes": [
              0,
              3
            ]
          },
          {
            "snippet": "Choose the appropriate Assessment Year (AY) and select Online as the mode of filing.",
            "reference_indexes": [
              0,
              3
            ]
          },
          {
            "snippet": "Select your status as Individual and choose ITR-1 (applicable if total income is up to ₹50 lakh from salary, one house property, and other sources like bank interest).",
            "reference_indexes": [
              1,
              4
            ]
          },
          {
            "snippet": "Click on Start New Filing and select the reason that applies to you.",
            "reference_indexes": [
              0,
              5
            ]
          },
          {
            "snippet": "Review your pre-filled data against your Form 16, Form 26AS, and AIS.",
            "reference_indexes": [
              2,
              6
            ]
          },
          {
            "snippet": "Fill in or verify sections for Gross Total Income, Deductions, and Taxes Paid.",
            "reference_indexes": [
              7,
              8
            ]
          },
          {
            "snippet": "Preview the tax computation summary, proceed to Validation, and Submit the return.",
            "reference_indexes": [
              7
            ]
          },
          {
            "snippet": "E-Verify the return using Aadhaar OTP or other available methods within 120 days of filing to complete the process.",
            "reference_indexes": [
              7
            ]
          }
        ]
      },
      {
        "type": "paragraph",
        "snippet": "If you tell me your sources of income (e.g., multiple house properties or capital gains) and whether you prefer the old or new tax regime, I can help you confirm if ITR-1 is the correct form for you."
      }
    ],
